"""Recursive descent over the grammar of SPEC section 6.2, and its inverse.

The AST is four frozen dataclasses, so two expressions that mean the same
thing compare equal, which is what makes the round-trip property test in
SPEC 13 a real check rather than a string comparison.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import datetime
from typing import Final, Union

from logsift.expr.lexer import (
    FilterSyntaxError,
    Literal,
    Mode,
    Token,
    TokenKind,
    literal_from,
    tokenize,
)
from logsift.record import Level

Node = Union["Or", "And", "Not", "Cmp"]


@dataclass(frozen=True, slots=True)
class Cmp:
    """``FIELD OP LITERAL``. Always that way round (SPEC 6.2)."""

    name: str
    op: str
    literal: Literal
    pos: int = field(default=0, compare=False)
    # Compiled once, at compile time, so an invalid pattern is an expression
    # error before any input is read. Excluded from equality because two
    # separately compiled patterns for the same source are not equal objects.
    regex: re.Pattern[str] | None = field(default=None, compare=False)


@dataclass(frozen=True, slots=True)
class Not:
    operand: Node


@dataclass(frozen=True, slots=True)
class And:
    left: Node
    right: Node


@dataclass(frozen=True, slots=True)
class Or:
    left: Node
    right: Node


_PRECEDENCE: Final[dict[type, int]] = {Or: 1, And: 2, Not: 3, Cmp: 4}


def parse(text: str) -> Node:
    """Parse a whole filter expression, or raise :class:`FilterSyntaxError`."""
    return _Parser(tokenize(text)).parse()


class _Parser:
    """One pass over the token list. Never backtracks; the grammar is LL(1)."""

    def __init__(self, tokens: list[Token]) -> None:
        self._tokens = tokens
        self._at = 0

    @property
    def _current(self) -> Token:
        return self._tokens[self._at]

    def _advance(self) -> Token:
        token = self._tokens[self._at]
        self._at += 1
        return token

    def _at_keyword(self, word: str) -> bool:
        token = self._current
        return token.kind is TokenKind.WORD and token.text.lower() == word

    def parse(self) -> Node:
        if self._current.kind is TokenKind.END:
            raise FilterSyntaxError("empty filter expression", 0, "an expression")
        node = self._or_expr()
        if self._current.kind is not TokenKind.END:
            raise FilterSyntaxError(
                f"unexpected {self._current.text!r}",
                self._current.pos,
                "'and', 'or', or end of expression",
            )
        return node

    def _or_expr(self) -> Node:
        node = self._and_expr()
        while self._at_keyword("or"):
            self._advance()
            node = Or(node, self._and_expr())
        return node

    def _and_expr(self) -> Node:
        node = self._not_expr()
        while self._at_keyword("and"):
            self._advance()
            node = And(node, self._not_expr())
        return node

    def _not_expr(self) -> Node:
        if self._at_keyword("not"):
            self._advance()
            return Not(self._not_expr())
        return self._primary()

    def _primary(self) -> Node:
        if self._current.kind is TokenKind.LPAREN:
            self._advance()
            node = self._or_expr()
            if self._current.kind is not TokenKind.RPAREN:
                raise FilterSyntaxError(
                    f"unexpected {self._current.text!r}"
                    if self._current.text
                    else "unclosed parenthesis",
                    self._current.pos,
                    "')'",
                )
            self._advance()
            return node
        return self._comparison()

    def _comparison(self) -> Node:
        name_token = self._advance()
        if name_token.kind is not TokenKind.WORD or name_token.text.lower() in (
            "and",
            "or",
        ):
            raise FilterSyntaxError(
                f"expected a field name, found {name_token.text!r}"
                if name_token.text
                else "expected a field name",
                name_token.pos,
                "a field name or '('",
            )

        op_token = self._advance()
        if op_token.kind is not TokenKind.OP:
            raise FilterSyntaxError(
                f"expected a comparison operator, found {op_token.text!r}"
                if op_token.text
                else "expected a comparison operator",
                op_token.pos,
                "one of == != < <= > >= ~",
            )

        literal_token = self._advance()
        literal = literal_from(literal_token)
        regex = None
        if op_token.text == "~":
            regex = _compile_regex(literal, literal_token.pos)
        return Cmp(name_token.text, op_token.text, literal, name_token.pos, regex)


def _compile_regex(literal: Literal, pos: int) -> re.Pattern[str]:
    """Compile the right-hand side of ``~`` (SPEC 6.3).

    The pattern must be a quoted string. Every other literal form has a
    comparison mode attached, and a regex has none: allowing ``level ~ WARN``
    would mean silently turning a level into text, which is the kind of
    implicit conversion the rest of the language refuses.
    """
    if literal.mode is not Mode.STRING:
        raise FilterSyntaxError(
            "the right-hand side of '~' must be a quoted string",
            pos,
            "a quoted regular expression",
        )
    assert isinstance(literal.value, str)
    try:
        return re.compile(literal.value)
    except re.error as exc:
        raise FilterSyntaxError(f"invalid regular expression: {exc}", pos) from exc


def unparse(node: Node) -> str:
    """Print ``node`` back to source that parses to an equal tree.

    Parentheses are added exactly where precedence or left-associativity would
    otherwise change the shape, so the output stays readable instead of being
    fully parenthesized.
    """
    if isinstance(node, Cmp):
        return f"{node.name} {node.op} {unparse_literal(node.literal)}"
    if isinstance(node, Not):
        return f"not {_wrap(node.operand, _PRECEDENCE[Not])}"
    keyword = "and" if isinstance(node, And) else "or"
    own = _PRECEDENCE[type(node)]
    # The right operand of a same-precedence operator needs parentheses: the
    # parser is left-associative, so `a or (b or c)` would otherwise print as
    # `a or b or c` and read back as `(a or b) or c`.
    return f"{_wrap(node.left, own)} {keyword} {_wrap(node.right, own + 1)}"


def _wrap(node: Node, minimum: int) -> str:
    text = unparse(node)
    return text if _PRECEDENCE[type(node)] >= minimum else f"({text})"


def unparse_literal(literal: Literal) -> str:
    """The source form of a literal, in the syntax that selects its mode."""
    value = literal.value
    if literal.mode is Mode.STRING:
        assert isinstance(value, str)
        return '"' + value.replace("\\", "\\\\").replace('"', '\\"') + '"'
    if literal.mode is Mode.BOOLEAN:
        return "true" if value else "false"
    if literal.mode is Mode.LEVEL:
        assert isinstance(value, Level)
        return value.name
    if literal.mode is Mode.TEMPORAL:
        assert isinstance(value, datetime)
        return value.isoformat()
    assert isinstance(value, float)
    return repr(value)

